cd /workspace && mkdir -p scratch && cat > scratch/extract.mjs <<'EOF'
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { inflateSync } from 'node:zlib';
import { dirname } from 'node:path';
const buf = readFileSync('/workspace/dataset/test20_executable');
const MAGIC = Buffer.from([0x4d,0x45,0x49,0x0c,0x0b,0x0a,0x0b,0x0e]);
let pos = buf.lastIndexOf(MAGIC);
console.log('cookie at', pos, 'filesize', buf.length);
// PyInstaller cookie: magic(8) + pkgLen(4) + toc(4) + tocLen(4) + pyvers(4) + pylibname(64)
const pkgLen = buf.readUInt32BE(pos+8);
const toc = buf.readUInt32BE(pos+12);
const tocLen = buf.readUInt32BE(pos+16);
const pyvers = buf.readUInt32BE(pos+20);
console.log({pkgLen, toc, tocLen, pyvers});
const pkgStart = pos + 8 + 4+4+4+4+64 - pkgLen;
console.log('pkgStart', pkgStart);
let p = pkgStart + toc;
const end = p + tocLen;
const entries = [];
while (p < end) {
  const entryLen = buf.readUInt32BE(p);
  const entryPos = buf.readUInt32BE(p+4);
  const cmprsdDataSize = buf.readUInt32BE(p+8);
  const uncmprsdDataSize = buf.readUInt32BE(p+12);
  const cmprsdFlag = buf.readUInt8(p+16);
  const typeCode = String.fromCharCode(buf.readUInt8(p+17));
  const nameRaw = buf.slice(p+18, p+entryLen);
  const name = nameRaw.toString('latin1').replace(/\0+$/,'');
  entries.push({name, typeCode, entryPos, cmprsdDataSize, uncmprsdDataSize, cmprsdFlag});
  p += entryLen;
}
console.log('entries', entries.length);
const want = entries.filter(e => /jsonschema_specifications|\.json$/.test(e.name));
for (const e of want) console.log(e.typeCode, e.cmprsdFlag, e.uncmprsdDataSize, e.name);
mkdirSync('/workspace/scratch/ex', {recursive:true});
for (const e of want) {
  let data = buf.slice(pkgStart + e.entryPos, pkgStart + e.entryPos + e.cmprsdDataSize);
  if (e.cmprsdFlag) { try { data = inflateSync(data); } catch(err) { console.log('inflate fail', e.name, err.message); continue; } }
  const out = '/workspace/scratch/ex/' + e.name.replace(/[^A-Za-z0-9._/-]/g,'_');
  mkdirSync(dirname(out), {recursive:true});
  writeFileSync(out, data);
}
console.log('extracted', want.length);
EOF
node scratch/extract.mjs 2>&1 | head -60

cd /workspace/scratch && cat > pyz.mjs <<'EOF'
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { inflateSync } from 'node:zlib';
const buf = readFileSync('/workspace/dataset/test20_executable');
const MAGIC = Buffer.from([0x4d,0x45,0x49,0x0c,0x0b,0x0a,0x0b,0x0e]);
const pos = buf.lastIndexOf(MAGIC);
const pkgLen = buf.readUInt32BE(pos+8), toc = buf.readUInt32BE(pos+12), tocLen = buf.readUInt32BE(pos+16);
const pkgStart = pos + 8 + 80 - pkgLen;
let p = pkgStart + toc; const end = p + tocLen; const entries=[];
while (p < end) { const L=buf.readUInt32BE(p); entries.push({name:buf.slice(p+18,p+L).toString('latin1').replace(/\0+$/,''),tc:String.fromCharCode(buf.readUInt8(p+17)),ep:buf.readUInt32BE(p+4),cs:buf.readUInt32BE(p+8),us:buf.readUInt32BE(p+12),cf:buf.readUInt8(p+16)}); p+=L; }
const pyz = entries.find(e=>e.tc==='z');
console.log('PYZ entry:', pyz.name, pyz.cs);
let data = buf.slice(pkgStart+pyz.ep, pkgStart+pyz.ep+pyz.cs);
if (pyz.cf) data = inflateSync(data);
// PYZ format: b'PYZ\0' + magic(4) + tocPos(4) ... then marshalled TOC
console.log('hdr', data.slice(0,4).toString(), 'tocPos', data.readUInt32BE(8));
const tocPos = data.readUInt32BE(8);
// marshal-parse minimal: TOC is a list/dict of (name, (typ, pos, len))
// Instead brute-force: scan for zlib streams and inflate, grep for target
mkdirSync('/workspace/scratch/mods',{recursive:true});
let found=0;
for (let i=0;i<data.length-2;i++){
  if (data[i]===0x78 && (data[i+1]===0x9c||data[i+1]===0xda||data[i+1]===0x01)) {
    try {
      const out = inflateSync(data.slice(i));
      const s = out.toString('latin1');
      if (s.includes('ipv6') && s.includes('is_email')) { writeFileSync('/workspace/scratch/mods/fmt_'+i+'.pyc', out); console.log('HIT at',i,out.length); found++; }
    } catch(e){}
  }
}
console.log('found',found);
EOF
node pyz.mjs 2>&1 | tail -20

