// Differential test corpus: [instance, schema] pairs as raw JSON strings.
// Raw strings matter: `1` vs `1.0` are the same JS number but different Python types.
export const CASES = [];
const C = (a, b) => CASES.push([a, b]);

// --- baseline / trivial ---
C('1', '{}');
C('1', '{"type":"object"}');
C('{"a":1}', '{"type":"object"}');
C('null', '{"type":"null"}');
C('null', '{}');
C('"s"', '{}');
C('[]', '{}');
C('{}', '{}');
C('true', '{}');
C('false', '{}');

// --- type keyword, all draft splits ---
for (const inst of ['1', '1.0', '1.5', 'true', 'false', 'null', '"1"', '[1]', '{"a":1}', '0', '-0.0', '1e2', '1E2', '2.0e1']) {
  for (const t of ['"integer"', '"number"', '"string"', '"boolean"', '"null"', '"array"', '"object"',
                   '["integer","string"]', '["number","null"]', '[]']) {
    C(inst, `{"type":${t}}`);
  }
}

// --- numeric bounds ---
for (const inst of ['5', '5.0', '4', '6', '-5', '0', '1e308', '-1e308']) {
  C(inst, '{"minimum":5}');
  C(inst, '{"maximum":5}');
  C(inst, '{"minimum":5,"maximum":5}');
  C(inst, '{"exclusiveMinimum":5}');
  C(inst, '{"exclusiveMaximum":5}');
  C(inst, '{"minimum":5.0,"exclusiveMaximum":5.5}');
  C(inst, '{"multipleOf":2}');
  C(inst, '{"multipleOf":2.5}');
  C(inst, '{"multipleOf":0.0001}');
}
C('0.0075', '{"multipleOf":0.0001}');
C('7', '{"multipleOf":3}');
C('-7', '{"multipleOf":3}');
C('123456789012345678901234567890', '{"type":"integer","maximum":123456789012345678901234567891}');
C('123456789012345678901234567892', '{"type":"integer","maximum":123456789012345678901234567891}');
C('10000000000000000000000', '{"multipleOf":1}');
C('9007199254740993', '{"maximum":9007199254740992}');

// --- draft4-style boolean exclusiveMinimum/Maximum (invalid in draft6+ metaschema) ---
C('5', '{"maximum":5,"exclusiveMaximum":true}');
C('5', '{"minimum":5,"exclusiveMinimum":false}');

// --- strings ---
for (const inst of ['"abc"', '"a"', '""', '"\\u00e9"', '"😀"', '"😀😀"', '"aXbXc"']) {
  C(inst, '{"minLength":1}');
  C(inst, '{"maxLength":1}');
  C(inst, '{"minLength":2,"maxLength":2}');
  C(inst, '{"pattern":"^a"}');
  C(inst, '{"pattern":"b"}');
  C(inst, '{"pattern":"[X]"}');
  C(inst, '{"pattern":"a.c"}');
}
C('"a\\nc"', '{"pattern":"a.c"}');
C('"abc"', '{"pattern":"(?i)ABC"}');
C('"abc"', '{"pattern":"a(?:b)c"}');
C('"abc"', '{"pattern":"\\\\w+"}');
C('"abc"', '{"pattern":"\\\\Aabc\\\\Z"}');
C('"abc"', '{"pattern":"(?P<x>a)bc"}');

// --- enum / const ---
C('1', '{"enum":[1,2,3]}');
C('1.0', '{"enum":[1,2,3]}');
C('true', '{"enum":[1]}');
C('1', '{"enum":[true]}');
C('1', '{"enum":[]}');
C('"a"', '{"enum":["a","b"]}');
C('[1,2]', '{"enum":[[1,2]]}');
C('{"a":1}', '{"enum":[{"a":1}]}');
C('{"a":1}', '{"enum":[{"a":1.0}]}');
C('1', '{"const":1}');
C('1', '{"const":1.0}');
C('1.0', '{"const":1}');
C('true', '{"const":1}');
C('1', '{"const":true}');
C('{"a":[1,{"b":null}]}', '{"const":{"a":[1,{"b":null}]}}');
C('null', '{"const":null}');
C('0', '{"const":false}');

// --- arrays ---
C('[1,2,3]', '{"minItems":2}');
C('[1]', '{"minItems":2}');
C('[1,2,3]', '{"maxItems":2}');
C('[1,1]', '{"uniqueItems":true}');
C('[1,1.0]', '{"uniqueItems":true}');
C('[true,1]', '{"uniqueItems":true}');
C('[0,false]', '{"uniqueItems":true}');
C('[[1],[1]]', '{"uniqueItems":true}');
C('[{"a":1},{"a":1}]', '{"uniqueItems":true}');
C('[null,null]', '{"uniqueItems":true}');
C('["1",1]', '{"uniqueItems":true}');
C('[1,2,3]', '{"uniqueItems":false}');
C('[1,"a",3]', '{"items":{"type":"integer"}}');
C('["a","b"]', '{"items":{"type":"integer"}}');
C('[1,"a"]', '{"prefixItems":[{"type":"integer"},{"type":"integer"}]}');
C('[1,"a",2]', '{"prefixItems":[{"type":"integer"}],"items":{"type":"integer"}}');
C('[1,2]', '{"prefixItems":[true],"unevaluatedItems":false}');
C('[1,2]', '{"prefixItems":[true,true],"unevaluatedItems":false}');
C('[1,2]', '{"items":true,"unevaluatedItems":false}');
C('[1]', '{"contains":{"type":"string"}}');
C('[1,"a"]', '{"contains":{"type":"string"}}');
C('[]', '{"contains":{"type":"string"}}');
C('[1,2]', '{"contains":{"type":"integer"},"maxContains":1}');
C('[1,2]', '{"contains":{"type":"integer"},"minContains":3}');
C('[]', '{"contains":{"type":"integer"},"minContains":0}');
C('[1,2,3]', '{"contains":{"type":"integer"},"minContains":2,"maxContains":2}');

// --- objects ---
C('{"a":1}', '{"required":["a"]}');
C('{"a":1}', '{"required":["b","c"]}');
C('{"a":1,"b":2}', '{"properties":{"a":{"type":"string"},"b":{"type":"string"}}}');
C('{"a":1}', '{"properties":{"a":{"type":"string"}},"required":["b"]}');
C('{"a":1,"b":2}', '{"minProperties":3}');
C('{"a":1,"b":2}', '{"maxProperties":1}');
C('{"a":1,"b":2}', '{"additionalProperties":false,"properties":{"a":true}}');
C('{"a":1,"b":2}', '{"additionalProperties":{"type":"string"},"properties":{"a":true}}');
C('{"ab":1,"b":2}', '{"patternProperties":{"^a":{"type":"string"}}}');
C('{"ab":1}', '{"patternProperties":{"^a":true},"additionalProperties":false}');
C('{"aa":1}', '{"propertyNames":{"maxLength":1}}');
C('{"aa":1,"bb":2}', '{"propertyNames":{"maxLength":1}}');
C('{"a":1,"b":2}', '{"properties":{"a":true},"unevaluatedProperties":false}');
C('{"a":1}', '{"properties":{"a":true},"unevaluatedProperties":false}');
C('{"a":1,"b":2}', '{"patternProperties":{"^a":true},"unevaluatedProperties":false}');
C('{"a":1,"b":2}', '{"additionalProperties":true,"unevaluatedProperties":false}');

// --- dependencies family ---
C('{"a":1}', '{"dependencies":{"a":["b"]}}');
C('{"a":1,"b":2}', '{"dependencies":{"a":["b"]}}');
C('{"a":1}', '{"dependencies":{"a":{"required":["b"]}}}');
C('{"a":1}', '{"dependentRequired":{"a":["b"]}}');
C('{"a":1}', '{"dependentSchemas":{"a":{"required":["b"]}}}');
C('{"a":1}', '{"dependencies":{"a":["b"]},"dependentRequired":{"a":["c"]}}');

// --- applicators ---
C('true', '{"allOf":[{"type":"string"},{"type":"number"}]}');
C('true', '{"anyOf":[{"type":"string"},{"type":"number"}]}');
C('true', '{"oneOf":[{"type":"string"},{"type":"number"}]}');
C('1', '{"oneOf":[{"type":"integer"},{"type":"number"}]}');
C('1', '{"oneOf":[{"type":"integer"},{"minimum":0}]}');
C('1', '{"not":{"type":"integer"}}');
C('1', '{"not":{}}');
C('1', '{"not":true}');
C('1', '{"not":false}');
C('1', '{"allOf":[{"minimum":5},{"maximum":0}],"type":"string"}');
C('1', '{"anyOf":[{"anyOf":[{"type":"string"}]}]}');
C('{"a":{"b":1}}', '{"properties":{"a":{"properties":{"b":{"type":"string"}}}}}');
C('{"a":{"b":1},"c":{"b":2}}', '{"properties":{"a":{"properties":{"b":{"type":"string"}}},"c":{"properties":{"b":{"type":"string"}}}}}');
C('[[1]]', '{"items":{"items":{"type":"string"}}}');

// --- if/then/else ---
C('1', '{"if":{"type":"integer"},"then":{"minimum":5}}');
C('1', '{"if":{"type":"string"},"then":{"minimum":5},"else":{"maximum":0}}');
C('1', '{"if":{"type":"integer"},"then":false}');
C('1', '{"if":false,"then":false,"else":false}');
C('1', '{"if":true,"then":false}');

// --- boolean subschemas ---
C('1', '{"properties":{"a":false}}');
C('{"a":1}', '{"properties":{"a":false}}');
C('{"a":1}', '{"additionalProperties":false}');
C('[1]', '{"items":false}');
C('[]', '{"items":false}');

// --- $ref ---
C('1', '{"definitions":{"s":{"type":"string"}},"$ref":"#/definitions/s"}');
C('1', '{"$defs":{"s":{"type":"string"}},"$ref":"#/$defs/s"}');
C('1', '{"$defs":{"s":{"type":"string"}},"$ref":"#/$defs/s","minimum":100}');
C('1', '{"$defs":{"s":{"type":"string"}},"allOf":[{"$ref":"#/$defs/s"}],"minimum":100}');
C('1', '{"$ref":"#"}');
C('{"a":{"a":1}}', '{"$defs":{"n":{"properties":{"a":{"$ref":"#/$defs/n"}},"type":"object"}},"$ref":"#/$defs/n"}');
C('1', '{"$defs":{"s":{"$anchor":"S","type":"string"}},"$ref":"#S"}');
C('1', '{"$id":"http://x/","$defs":{"s":{"$id":"sub","type":"string"}},"$ref":"sub"}');
C('{"a":1}', '{"$defs":{"o":{"type":"object","properties":{"a":{"$ref":"#/$defs/s"}}},"s":{"type":"string"}},"$ref":"#/$defs/o"}');
C('1', '{"$defs":{"s":{"type":"string"}},"$ref":"#/$defs/s","$comment":"x"}');

// --- $schema dialect switching (drives evolve divergence) ---
const SCHEMAS = ['http://json-schema.org/draft-04/schema#', 'http://json-schema.org/draft-06/schema#',
                 'http://json-schema.org/draft-07/schema#', 'https://json-schema.org/draft/2019-09/schema',
                 'https://json-schema.org/draft/2020-12/schema', 'http://json-schema.org/schema#',
                 'http://json-schema.org/draft-04/schema', 'https://json-schema.org/draft/2020-12/schema#'];
for (const s of SCHEMAS) {
  C('1', `{"$schema":"${s}"}`);
  C('1', `{"$schema":"${s}","const":2}`);
  C('1', `{"$schema":"${s}","type":"integer"}`);
  C('1.0', `{"$schema":"${s}","type":"integer"}`);
  C('{"a":1}', `{"$schema":"${s}","dependencies":{"a":["b"]}}`);
  C('{"a":1}', `{"$schema":"${s}","dependentRequired":{"a":["b"]}}`);
  C('1', `{"$schema":"${s}","if":{"type":"integer"},"then":{"minimum":5}}`);
  C('[1]', `{"$schema":"${s}","contains":{"type":"string"}}`);
  C('{"a":1,"b":2}', `{"$schema":"${s}","properties":{"a":true},"unevaluatedProperties":false}`);
}

// --- format (never asserted: no format_checker passed) ---
C('"not-an-email"', '{"format":"email"}');
C('"nope"', '{"format":"date"}');
C('"("', '{"format":"regex"}');
C('1', '{"format":"unknown-format"}');

// --- content / annotations (no assertion) ---
C('"x"', '{"contentMediaType":"application/json","contentEncoding":"base64"}');
C('1', '{"title":"t","description":"d","default":3,"examples":[1],"deprecated":true,"readOnly":true,"writeOnly":true}');

// --- ErrorTree collapse cases (same path + same validator key) ---
C('true', '{"allOf":[{"type":"string"},{"type":"number"},{"type":"array"}]}');
C('true', '{"allOf":[{"type":"string"}],"anyOf":[{"type":"number"}]}');
C('{"a":true}', '{"properties":{"a":{"allOf":[{"type":"string"},{"type":"number"}]}}}');
C('[true,true]', '{"items":{"allOf":[{"type":"string"},{"type":"number"}]}}');
C('1', '{"allOf":[{"minimum":5},{"minimum":6}]}');
C('1', '{"allOf":[{"minimum":5}],"minimum":6}');
C('{"a":1,"b":1}', '{"properties":{"a":{"type":"string"},"b":{"type":"string"}},"required":["c","d"]}');
C('[1,2]', '{"items":{"type":"string"}}');

// --- schemas that fail check_schema on some draft (expect exit 1) ---
C('1', 'true');
C('1', 'false');
C('1', '{"type":123}');
C('1', '{"type":"nope"}');
C('1', '{"properties":{"a":true}}');
C('1', '{"items":[{"type":"integer"}],"additionalItems":false}');
C('1', '{"minLength":-1}');
C('1', '{"required":[]}');
C('1', '{"required":["a","a"]}');
C('1', '{"exclusiveMaximum":true,"maximum":5}');
C('1', '{"$defs":{"s":{"type":"string"}}}');
C('1', '{"enum":[1,1]}');
