C('1', '{"id":"http://x/y","type":"integer"}');
C('1', '{"definitions":{"s":{"type":"string"}}}');
C('1', '{"unknownKeyword":{"deep":[1,2]}}');

// --- unicode / odd keys ---
C('{"\\u00e9":1}', '{"required":["\\u00e9"]}');
C('{"":1}', '{"required":[""]}');
C('{"a b":1}', '{"properties":{"a b":{"type":"string"}}}');
C('{"1":1}', '{"properties":{"1":{"type":"string"}}}');
C('[{"1":1}]', '{"items":{"properties":{"1":{"type":"string"}}}}');

