// Differential runner: executes the Python reference executable and the Node port
// over the corpus and reports every mismatch (stdout byte-for-byte, plus exit code).
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:process' === 'x' ? {} : await import('node:fs');
import { CASES } from './corpus.mjs';

const EXE = '/workspace/dataset/test20_executable';
const JS = process.argv[2] || '/output/test20.mjs';
const only = process.argv[3] ? Number(process.argv[3]) : null;

function run(cmd, args) {
  try {
    const out = execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 1 << 26 });
    return { out, code: 0 };
  } catch (e) {
    return { out: e.stdout == null ? '' : e.stdout, code: e.status == null ? -1 : e.status };
  }
}

let pass = 0;
const fails = [];
const cases = only == null ? CASES : [CASES[only]];
for (let i = 0; i < cases.length; i++) {
  const [a, b] = cases[i];
  const py = run(EXE, ['--a', a, '--b', b]);
  const js = run('node', [JS, '--a', a, '--b', b]);
  const okCode = (py.code === 0) === (js.code === 0);
  if (py.out === js.out && okCode) { pass++; continue; }
  fails.push({ i: only == null ? i : only, a, b, py, js });
}

console.log(`\n=== ${pass}/${cases.length} pass, ${fails.length} fail ===\n`);
for (const f of fails.slice(0, Number(process.env.SHOW || 25))) {
  console.log(`--- case #${f.i}`);
  console.log(`  --a ${f.a}`);
  console.log(`  --b ${f.b}`);
  console.log(`  py(exit ${f.py.code}): ${JSON.stringify(f.py.out)}`);
  console.log(`  js(exit ${f.js.code}): ${JSON.stringify(f.js.out)}`);
  if (f.py.out && f.js.out) {
    const pl = f.py.out.split('\n'), jl = f.js.out.split('\n');
    const LBL = ['v4', 'v6', 'v7', 'v2019', 'v2020', 'e4', 'e6', 'e7', 'e2019', 'e2020',
                 'c4', 'c6', 'c7', 'c2019', 'c2020', 'tree', 'fmt', 'auto', 'evolved', 'eq'];
    for (let k = 0; k < Math.max(pl.length, jl.length); k++) {
      if (pl[k] !== jl[k]) console.log(`    line ${k} (${LBL[k] || '?'}): py=${JSON.stringify(pl[k])} js=${JSON.stringify(jl[k])}`);
    }
  }
}
if (fails.length) {
  const fs = await import('node:fs');
  fs.writeFileSync('/workspace/scratch/failures.json', JSON.stringify(fails, null, 1));
  console.log(`\n(full failure list: /workspace/scratch/failures.json)`);
}
process.exit(fails.length ? 1 : 0);

