// Fast differential check: Node port vs recorded Python reference outputs.
// usage: node check.mjs [jsPath] [--verbose] [--case N]
import { execFile } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const exp = JSON.parse(readFileSync('/workspace/scratch/expected.json', 'utf8'));
const args = process.argv.slice(2);
const JS = args.find(a => !a.startsWith('--')) || '/output/test20.mjs';
const caseIdx = args.includes('--case') ? Number(args[args.indexOf('--case') + 1]) : null;
const LBL = ['v4','v6','v7','v2019','v2020','e4','e6','e7','e2019','e2020','c4','c6','c7','c2019','c2020','tree','fmt','auto','evolved','eq'];
const idxs = caseIdx == null ? exp.map((_, i) => i) : [caseIdx];
const N = 16;
const results = new Array(idxs.length);
let next = 0;
function one() {
  return new Promise(res => {
    const k = next++;
    if (k >= idxs.length) return res(false);
    const i = idxs[k]; const { a, b } = exp[i];
    execFile('node', [JS, '--a', a, '--b', b], {encoding:'utf8', maxBuffer:1<<26}, (err, stdout, stderr) => {
      results[k] = { i, out: stdout ?? '', code: err ? (err.code ?? -1) : 0, stderr: stderr ?? '' };
      res(true);
    });
  });
}
async function worker() { while (await one()) {} }
await Promise.all(Array.from({length:N}, worker));
const fails = [];
for (let k = 0; k < idxs.length; k++) {
  const i = idxs[k], e = exp[i], r = results[k];
  const codeOk = (e.code === 0) === (r.code === 0);
  if (e.out === r.out && codeOk) continue;
  fails.push({ i, a: e.a, b: e.b, pyOut: e.out, pyCode: e.code, jsOut: r.out, jsCode: r.code, jsErr: r.stderr.slice(0, 900) });
}
console.log(`\n=== ${idxs.length - fails.length}/${idxs.length} pass, ${fails.length} FAIL ===\n`);
const SHOW = Number(process.env.SHOW || 20);
for (const f of fails.slice(0, SHOW)) {
  console.log(`--- #${f.i}\n  --a ${f.a}\n  --b ${f.b}`);
  console.log(`  py exit=${f.pyCode} js exit=${f.jsCode}`);
  const pl = f.pyOut.split('\n'), jl = f.jsOut.split('\n');
  if (f.pyOut && f.jsOut) {
    for (let k = 0; k < Math.max(pl.length, jl.length); k++)
      if (pl[k] !== jl[k]) console.log(`    ${LBL[k]||'line'+k}: py=${JSON.stringify(pl[k])} js=${JSON.stringify(jl[k])}`);
  } else {
    console.log(`    py=${JSON.stringify(f.pyOut)}\n    js=${JSON.stringify(f.jsOut)}`);
  }
  if (f.jsErr) console.log(`    jsErr: ${f.jsErr.split('\n').slice(0,6).join(' | ')}`);
}
if (fails.length) { writeFileSync('/workspace/scratch/failures.json', JSON.stringify(fails, null, 1)); console.log(`\n(all failures -> /workspace/scratch/failures.json)`); }
process.exit(fails.length ? 1 : 0);
