// Ad-hoc differential runner for arbitrary cases.
//   node adhoc.mjs cases.json          # JSON array of [instanceJson, schemaJson]
//   node adhoc.mjs --a '1' --b '{}'    # single pair
// Prints PASS/FAIL per case with per-line diffs. Exit 1 if any FAIL.
import { execFile } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test20_executable';
const JS = process.env.JS || '/output/test20.mjs';
const LBL = ['v4','v6','v7','v2019','v2020','e4','e6','e7','e2019','e2020','c4','c6','c7','c2019','c2020','tree','fmt','auto','evolved','eq'];
const av = process.argv.slice(2);
let cases;
if (av[0] === '--a') cases = [[av[1], av[3]]];
else cases = JSON.parse(readFileSync(av[0], 'utf8'));
const sh = (cmd, args) => new Promise(r =>
  execFile(cmd, args, { encoding: 'utf8', maxBuffer: 1 << 26 },
    (e, so, se) => r({ out: so ?? '', code: e ? (e.code ?? -1) : 0, err: se ?? '' })));
let bad = 0, next = 0;
const res = new Array(cases.length);
async function worker() {
  for (;;) {
    const i = next++; if (i >= cases.length) return;
    const [a, b] = cases[i];
    const [py, js] = await Promise.all([sh(EXE, ['--a', a, '--b', b]), sh('node', [JS, '--a', a, '--b', b])]);
    res[i] = { a, b, py, js };
  }
}
await Promise.all(Array.from({ length: 12 }, worker));
for (let i = 0; i < cases.length; i++) {
  const { a, b, py, js } = res[i];
  const ok = py.out === js.out && (py.code === 0) === (js.code === 0);
  if (ok) { console.log(`PASS #${i}`); continue; }
  bad++;
  console.log(`FAIL #${i}\n  --a ${a}\n  --b ${b}\n  py exit=${py.code}  js exit=${js.code}`);
  const pl = py.out.split('\n'), jl = js.out.split('\n');
  if (py.out && js.out) for (let k = 0; k < Math.max(pl.length, jl.length); k++)
    if (pl[k] !== jl[k]) console.log(`    ${LBL[k] || 'line' + k}: py=${JSON.stringify(pl[k])} js=${JSON.stringify(jl[k])}`);
  else console.log(`    py=${JSON.stringify(py.out)}\n    js=${JSON.stringify(js.out)}`);
  if (js.err) console.log(`    jsErr: ${js.err.split('\n').slice(0, 5).join(' | ')}`);
}
console.log(`\n${cases.length - bad}/${cases.length} pass, ${bad} fail`);
process.exit(bad ? 1 : 0);
EOF
